#include <cstdint>
#include <iostream>
#include <limits>

int main() {
    int count = 42;                 // usually 32 bits
    long long big = 9'000'000'000;  // at least 64 bits
    double price = 19.99;           // 64-bit floating point
    float ratio = 0.5f;             // f suffix: float literal
    bool done = false;
    char letter = 'A';
    std::int32_t exact = -7;        // exactly 32 bits, from <cstdint>
    unsigned int u = 0;

    std::cout << sizeof(int) << ' ' << sizeof(long long) << '\n';   // 4 8 (typical)
    std::cout << std::numeric_limits<int>::max() << '\n';           // 2147483647
    std::cout << 7 / 2 << ' ' << 7 / 2.0 << '\n';                   // 3 3.5
    std::cout << u - 1 << '\n';                                     // 4294967295: wraps
    std::cout << count + exact << ' ' << big << ' ' << price * ratio
              << ' ' << done << ' ' << letter << '\n';              // 35 9000000000 9.995 0 A
}

