int main() {
    auto n = 42;              // int
    auto d = 2.5;             // double
    auto s = std::string{"hi"};
    int zero{};               // value-initialised: 0
    // int bad{3.7};          // error: narrowing conversion
    int truncated = 3.7;      // compiles, silently 3 (warns with -Wconversion)

    std::vector<int> a(3, 7); // three elements: 7 7 7
    std::vector<int> b{3, 7}; // two elements: 3 7 (initializer_list wins)

    const std::vector<int>& ref = a;
    auto copy = ref;          // std::vector<int>: const and & dropped, real copy
    const auto& alias = ref;  // no copy

    std::cout << n + d << ' ' << s << ' ' << zero << ' ' << truncated << '\n';  // 44.5 hi 0 3
    std::cout << a.size() << ' ' << b.size() << ' '
              << copy.size() << ' ' << alias.size() << '\n';                   // 3 2 3 3
}

