int main() {
    std::vector<int> scores{90, 45, 72, 100, 58};

    int passed = 0;
    for (int s : scores) {                 // range-based for
        if (s < 50) continue;              // skip failures
        ++passed;
    }

    for (int i = 0; i < 3; ++i) std::cout << i << ' ';   // 0 1 2
    std::cout << '\n';

