        std::cout << "perfect score\n";

    char cmd = 'q';
    switch (cmd) {
        case 'a': std::cout << "add\n"; break;
        case 'q':
        case 'x': std::cout << "quit\n"; break;   // two labels share code
        default:  std::cout << "unknown\n";
    }
    std::cout << passed << ' ' << n << '\n';     // 4 243
}

