#include <array>
#include <iostream>
#include <stdexcept>
#include <vector>

int main() {
    int raw[3] = {1, 2, 3};                // C array: fixed, unchecked
    std::array<int, 3> fixed{4, 5, 6};     // fixed size, knows its size, copyable

    std::vector<int> v;                    // dynamic array on the heap
    v.reserve(10);                         // optional: preallocate
    for (int i = 0; i < 5; ++i) v.push_back(i * i);   // 0 1 4 9 16
    v.pop_back();                          // removes 16

    std::cout << v.size() << ' ' << v.front() << ' ' << v.back() << '\n';  // 4 0 9
    std::cout << v[1] << '\n';             // 1, unchecked access
    try {
        std::cout << v.at(10) << '\n';     // checked
    } catch (const std::out_of_range&) {
        std::cout << "out of range\n";
    }
    std::cout << raw[0] + fixed[2] << ' ' << fixed.size() << '\n';   // 7 3

    std::vector<std::vector<int>> grid(2, std::vector<int>(3, 0));   // 2 x 3 zeros
    grid[1][2] = 7;
}

