class Inventory {
public:
    void add(std::string item) { items_.push_back(std::move(item)); }  // modifies: not const
    std::size_t count() const { return items_.size(); }               // read-only
    bool has(const std::string& name) const {
        ++lookups_;                                   // allowed: lookups_ is mutable
        for (const auto& i : items_) if (i == name) return true;
        return false;
    }
    int lookups() const { return lookups_; }
private:
    std::vector<std::string> items_;
    mutable int lookups_ = 0;                         // statistics, not logical state
};

void report(const Inventory& inv) {                   // promises not to modify inv
    std::cout << inv.count() << ' ' << inv.has("rope") << '\n';
    // inv.add("x");                                  // error: add() is not const
}

int main() {
    const int max_items = 10;
    Inventory inv;
    inv.add("rope");
    report(inv);                                                    // 1 1
    std::cout << max_items - inv.count() << ' ' << inv.lookups() << '\n';  // 9 1
}

#include <iostream>

struct Node { int value; Node* next; };   // can be null, can be repointed

int main() {
    int x = 10;
    int* p = &x;            // p holds the address of x
    *p = 20;                // write through the pointer
    std::cout << x << ' ' << (p != nullptr) << '\n';   // 20 1

    int arr[] = {1, 2, 3, 4};
    int* it = arr;          // array decays to a pointer to its first element
    it += 2;                // pointer arithmetic: now at arr[2]
    std::cout << *it << ' ' << it[1] << '\n';          // 3 4

    const int* read_only = &x;   // can't modify *read_only, can repoint
    int* const fixed = &x;       // can modify *fixed, can't repoint
    *fixed = 30;
    std::cout << *read_only << '\n';                   // 30

    Node c{3, nullptr}, b{2, &c}, a{1, &b};
    for (Node* n = &a; n != nullptr; n = n->next)      // n->value is (*n).value
        std::cout << n->value << ' ';                  // 1 2 3
    std::cout << '\n';
}

