};

void inspect(const Texture& t) { std::cout << "inspect " << t.name << '\n'; }  // no ownership

int main() {
    auto solo = std::make_unique<Texture>("grass");     // sole owner
    inspect(*solo);
    std::unique_ptr<Texture> owner = std::move(solo);   // ownership moved; solo is null

    auto shared = std::make_shared<Texture>("sky");
    std::vector<std::shared_ptr<Texture>> users{shared, shared};
    std::cout << shared.use_count() << '\n';            // 3

    std::weak_ptr<Texture> watcher = shared;            // doesn't affect the count
    shared.reset();
    users.clear();                                      // last owner gone: "free sky"
    std::cout << watcher.expired() << '\n';             // 1
}                                                       // "free grass"

