enum Color { Red, Green };                      // old style: names leak, converts to int
enum class Level : std::uint8_t { Debug, Info, Warn, Error };   // scoped, one byte

const char* label(Level l) {
    using enum Level;                           // C++20: no Level:: prefix needed below
    switch (l) {                                // -Wall warns if a case is missing
        case Debug: return "debug";
        case Info:  return "info";
        case Warn:  return "warn";
        case Error: return "error";
    }
    return "?";
}

int main() {
    Level l = Level::Warn;
    // int bad = l;                             // error: no implicit conversion
    int n = static_cast<int>(l);                // 2 (C++23: std::to_underlying(l))
    bool loud = l >= Level::Warn;               // same-enum comparison is fine
    int c = Green;                              // compiles: unscoped enums convert silently
    std::cout << label(l) << ' ' << n << ' ' << loud << ' ' << c << '\n';  // warn 2 1 1
}

#include <iostream>
