#include <set>
#include <string>
#include <unordered_map>
#include <vector>

int main() {
    std::vector<std::string> words{"to", "be", "or", "not", "to", "be"};

    std::unordered_map<std::string, int> freq;       // hash table, average O(1)
    for (const auto& w : words) ++freq[w];           // [] inserts 0 if missing

    std::map<std::string, int> sorted(freq.begin(), freq.end());   // ordered by key
    for (const auto& [word, n] : sorted)             // structured bindings
        std::cout << word << '=' << n << ' ';        // be=2 not=1 or=1 to=2
    std::cout << '\n';

    std::set<std::string> unique(words.begin(), words.end());
    std::cout << unique.size() << ' ' << unique.contains("or") << '\n';   // 4 1

    if (auto it = freq.find("xyz"); it == freq.end())
        std::cout << "no xyz\n";                     // find doesn't insert; [] would
    std::cout << freq.size() << '\n';                // 4
}

#include <iostream>
#include <list>
#include <vector>

int main() {
    std::vector<int> v{3, 1, 4, 1, 5, 9};
    for (auto it = v.begin(); it != v.end(); ++it)   // [begin, end): end is one past the last
        *it *= 10;

    for (auto it = v.rbegin(); it != v.rend(); ++it) std::cout << *it << ' ';
    std::cout << '\n';                               // 90 50 10 40 10 30

    auto third = v.begin() + 2;                      // random access: jump by n
    std::cout << *third << ' ' << (v.end() - v.begin()) << '\n';   // 40 6

    std::list<int> l{1, 2, 3};
    auto li = l.begin();
    ++li;                                            // bidirectional: no li + 2
    l.insert(li, 99);                                // list iterators stay valid: 1 99 2 3

    for (auto it = v.begin(); it != v.end();)        // erase while iterating:
        it = (*it == 10) ? v.erase(it) : it + 1;     // continue from what erase returns
    std::erase(v, 90);                               // C++20 one-liner
    for (int x : v) std::cout << x << ' ';           // 30 40 50
    std::cout << '\n';
}

#include <algorithm>
#include <functional>
#include <iostream>
#include <memory>
#include <vector>

int main() {
    std::vector<int> v{5, 2, 8, 1};
    int threshold = 3;

    auto above = [threshold](int x) { return x > threshold; };     // capture by value
    std::cout << std::count_if(v.begin(), v.end(), above) << '\n';  // 2

    int calls = 0;
    std::sort(v.begin(), v.end(), [&calls](int a, int b) { ++calls; return a > b; });
    std::cout << v[0] << ' ' << (calls > 0) << '\n';                // 8 1

    auto add = [](auto a, auto b) { return a + b; };                // generic lambda
    std::cout << add(1, 2) << ' ' << add(1.5, 2.0) << '\n';         // 3 3.5

    auto counter = [n = 0]() mutable { return ++n; };               // own state
    counter(); counter();
    std::cout << counter() << '\n';                                 // 3

    auto owned = [p = std::make_unique<int>(7)] { return *p; };     // move-only capture
    std::function<int(int)> twice = [](int x) { return 2 * x; };    // type-erased
    std::cout << owned() + twice(4) << '\n';                        // 15
}

#include <algorithm>
