struct Order { std::string customer; double amount; };

int main() {
    std::vector<Order> orders{{"ann", 30.0}, {"bob", 120.5}, {"cy", 75.0}, {"ann", 9.5}};

    std::sort(orders.begin(), orders.end(),
              [](const Order& a, const Order& b) { return a.amount > b.amount; });
    std::cout << orders.front().customer << '\n';                     // bob

    double total = std::accumulate(orders.begin(), orders.end(), 0.0,  // 0.0, not 0!
        [](double sum, const Order& o) { return sum + o.amount; });
    bool any_big = std::any_of(orders.begin(), orders.end(),
                               [](const Order& o) { return o.amount > 100; });

    std::vector<std::string> names;
    std::transform(orders.begin(), orders.end(), std::back_inserter(names),
                   [](const Order& o) { return o.customer; });
    std::sort(names.begin(), names.end());
    names.erase(std::unique(names.begin(), names.end()), names.end());  // dedupe
    std::cout << total << ' ' << any_big << ' ' << names.size() << '\n'; // 235 1 3
}

