#include <iostream>
#include <stdexcept>
#include <string>

struct Guard {
    ~Guard() { std::cout << "cleanup\n"; }      // runs during stack unwinding
};

int parse_port(const std::string& s) {
    Guard g;
    int port = std::stoi(s);                     // throws std::invalid_argument on "abc"
    if (port < 1 || port > 65535)
        throw std::out_of_range("port out of range: " + s);
    return port;
}

int main() {
    for (std::string input : {"8080", "99999", "abc"}) {
        try {
            int port = parse_port(input);
            std::cout << "port " << port << '\n';
        } catch (const std::out_of_range& e) {   // most specific first
            std::cout << "range error: " << e.what() << '\n';
        } catch (const std::exception& e) {      // base of all standard exceptions
            std::cout << "bad input: " << e.what() << '\n';
        }
    }
}   // each input prints "cleanup" before its result or error

#include <iostream>
#include <utility>
#include <vector>

class Buffer {
public:
    explicit Buffer(std::size_t n) : data_(n) {}
    Buffer(const Buffer& o) : data_(o.data_) { std::cout << "copy\n"; }
    Buffer(Buffer&& o) noexcept : data_(std::move(o.data_)) { std::cout << "move\n"; }
    Buffer& operator=(const Buffer&) = default;
    Buffer& operator=(Buffer&&) noexcept = default;
    std::size_t size() const { return data_.size(); }
private:
    std::vector<char> data_;
};

Buffer make() { Buffer b(1024); return b; }   // NRVO or implicit move, never a copy

int main() {
    Buffer a(100);
    Buffer b = a;                // copy: a is an lvalue
    Buffer c = std::move(a);     // move: std::move casts a to Buffer&&
    Buffer d = make();           // typically prints nothing: elided
    std::vector<Buffer> v;
    v.push_back(Buffer(8));      // move: the temporary is an rvalue
    std::cout << b.size() << ' ' << c.size() << ' ' << d.size() << '\n';  // 100 100 1024
}

