    std::vector<std::string> lines_;
    std::unique_ptr<int[]> index_;      // makes Document move-only automatically
public:
    explicit Document(std::string t) : title_{std::move(t)} {}
};

// Rule of five: only for a class whose job IS owning one resource.
class CBuffer {
    char* p_;
    std::size_t n_;
public:
    explicit CBuffer(std::size_t n) : p_{new char[n]{}}, n_{n} {}
    ~CBuffer() { delete[] p_; }
    CBuffer(const CBuffer& o) : p_{new char[o.n_]}, n_{o.n_} { std::memcpy(p_, o.p_, n_); }
    CBuffer(CBuffer&& o) noexcept : p_{std::exchange(o.p_, nullptr)}, n_{std::exchange(o.n_, 0)} {}
    CBuffer& operator=(CBuffer o) noexcept {   // copy-and-swap: covers copy AND move
        std::swap(p_, o.p_); std::swap(n_, o.n_); return *this;
    }
};

int main() {
    Document d{"notes"};
    Document d2 = std::move(d);         // OK; `Document d3 = d2;` would not compile
    CBuffer a{16}, b{a};                // deep copy
    b = std::move(a);
}

