int main() {
    std::atomic<int> hits{0};             // indivisible ++, no data race
    std::mutex m;
    std::vector<int> finished;            // shared, guarded by m

    {
        std::vector<std::jthread> workers;            // C++20: joins in its destructor
        for (int id = 0; id < 4; ++id) {
            workers.emplace_back([&, id] {
                for (int i = 0; i < 1000; ++i) ++hits;
                std::scoped_lock lock{m};              // unlocks at end of scope
                finished.push_back(id);
            });
        }
    }                                                  // all threads joined here

    std::cout << hits << ' ' << finished.size() << '\n';   // 4000 4

    std::jthread ticker([](std::stop_token st) {       // cooperative cancellation
        while (!st.stop_requested()) std::this_thread::yield();
    });
    ticker.request_stop();               // the destructor would do this too, then join
}

