std::string payload;                     // ordinary, non-atomic data
std::atomic<bool> ready{false};

void producer() {
    payload = "hello";                                 // (1) plain write
    ready.store(true, std::memory_order_release);      // (2) publishes everything before it
}

void consumer() {
    while (!ready.load(std::memory_order_acquire))     // (3) synchronises with (2)
        std::this_thread::yield();
    assert(payload == "hello");                        // (4) safe: (1) happens-before (4)
}

std::atomic<int> max_seen{0};
void update_max(int v) {                               // lock-free CAS loop
    int cur = max_seen.load(std::memory_order_relaxed);
    while (cur < v && !max_seen.compare_exchange_weak(cur, v, std::memory_order_relaxed)) {
        // on failure `cur` now holds the latest value; the loop re-checks it
    }
}

int main() {
    std::jthread c{consumer}, p{producer};
    std::jthread a{update_max, 7}, b{update_max, 3};
}

